def max_path_sum(root):
    best = root.value if root is not None else 0
    def gain(node):
        nonlocal best
        if node is None:
            return 0
        left = max(gain(node.left), 0)
        right = max(gain(node.right), 0)
        if node.value + left + right > best:
            best = node.value + left + right
        return node.value + max(left, right)
    gain(root)
    return best

bruteForceCode:
def max_path_sum(root):
    def best_down(node):
        if node is None:
            return 0
        return node.value + max(0, best_down(node.left), best_down(node.right))
    best = None
    stack = [root] if root is not None else []
    while stack:
        node = stack.pop()
        if node is None:
            continue
        candidate = node.value + max(0, best_down(node.left)) + max(0, best_down(node.right))
        if best is None or candidate > best:
            best = candidate
        stack.append(node.left)
        stack.append(node.right)
    return best
